/// <summary>
/// N.Freidenberger TASK 12587 21.11.2024
/// </summary>
internal final class AVAPostArchivingReportsService  extends SysOperationServiceBase
{
    FromDate        fromDate;
    ToDate          toDate;
    AVADAIReport    avaDAIReport;

}

Method.Source:
/// <summary>
/// N.Freidenberger TASK 12587 21.11.2024
/// </summary>
/// <param name = "_dataContract"></param>
public void process(AVAPostArchivingReportsContract _dataContract)
{


    fromDate  = _dataContract.parmFromDate();
    toDate    = _dataContract.parmToDate();

    while select avaDAIReport
    {
        switch (avaDAIReport.AckRefTableName)
        {
            case tableStr(CustConfirmJour) :
                this.postArchivingCustConfirmJour(avaDAIReport.AckRefTableFieldName);   
                break;
            case tableStr(CustPackingSlipJour) :
                this.postArchivingCustPackingSlipJour(avaDAIReport.AckRefTableFieldName);
                break;
            case tableStr(CustInvoiceJour):
                this.postArchivingCustInvoiceJour(avaDAIReport.AckRefTableFieldName);
                break;
            case tableStr(CustQuotationConfirmJour) :
            case tableStr(CustQuotationJour) :
                this.postArchivingCustQuotationConfirmJour(avaDAIReport.AckRefTableFieldName);
                break;
            default :
                error(strFmt("@NDX:NXAPostArchivingTableMissed",avaDAIReport.AckRefTableName));
                break;
        }
    }

}

/// <summary>
/// N.Freidenberger TASK 12587 21.11.2024
/// </summary>
/// <param name = "_ackRefFieldName">_ackRefFieldName</param>
public void postArchivingCustConfirmJour(Str       _ackRefFieldName)
{
    AVADAIReportExportTable         avaDAIReportExportTable;
    CustConfirmJour                 CustConfirmJour;
    FieldId                         refFieldId = fieldName2Id(tableNum(CustConfirmJour),_ackRefFieldName);
    SalesConfirmJournalPrint        custConfirmJournalPrint = SalesConfirmJournalPrint::construct();
    SRSPrintDestinationSettings     srsPrintDestinationSetting; // = new SRSPrintDestinationSettings();
  //  srsPrintDestinationSetting.printMediumType(SRSPrintMediumType::File);
  //  Set                             confirmJourSet = new Set(Types::Record);

   // SrsReportDataContract       locreportContract = this.parmReportContract();
   // SRSPrintDestinationSettings printerSettings = locreportContract.parmPrintSettings();




 //   custConfirmJournalPrint.parmPrinterSettingsFormLetter(srsPrintDestinationSetting.pack());

    while select custConfirmJour
        where  custConfirmJour.ConfirmDate >= fromDate
           &&  (CustConfirmJour.ConfirmDate <= toDate || toDate == dateNull())
        notexists join avaDAIReportExportTable
            where CustConfirmJour.(refFieldId) == avaDAIReportExportTable.RefNum
    {

        Args        args = new Args();
        args.record(custConfirmJour);

        custConfirmJournalPrint = SalesConfirmJournalPrint::construct();
        custConfirmJournalPrint.parmPrintFormletter(NoYes::Yes);
        custConfirmJournalPrint.parmUsePrintManagement(false);


        TradeDocumentReportController formLetterController = SalesConfirmController::construct();

        formLetterController.parmArgs(args);

        formLetterController.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::SalesOrderConfirmation).getDefaultReportFormat());
        formLetterController.parmAVAPrintInMemory(true);
        formLetterController.parmAVAreportRecord(custConfirmJour);

        formLetterController.parmShowDialog(false);
        formLetterController.parmDialogCaption("@SYS22766");
        SrsReportDataContract  reportContract = formLetterController.parmReportContract();

        srsPrintDestinationSetting  =  reportContract.parmPrintSettings();   
        srsPrintDestinationSetting.printMediumType(SRSPrintMediumType::File);
        srsPrintDestinationSetting.fileFormat(SRSReportFileFormat::PDF);
        srsPrintDestinationSetting.fileName(strfmt("%1",custConfirmJour.ConfirmId));


        custConfirmJournalPrint.parmPrinterSettingsFormLetter(srsPrintDestinationSetting.pack());

        args.caller(custConfirmJournalPrint);
        args.parmEnumType(enumNum(PrintCopyOriginal));
        args.parmEnum(PrintCopyOriginal::OriginalPrint);


      // formLetterController.parmDefaultCopyPrintJobSettings(srsPrintDestinationSetting);
       // formLetterController.srsPrintDestinationSetting(srsPrintDestinationSetting);
     //   reportContract.parmPrintSettings(srsPrintDestinationSetting);

        formLetterController.startOperation();
    }


}

