/// <summary>
/// N.Freidenberger TASK 12587 21.11.2024
/// </summary>
/// <param name = "_ackRefFieldName">_ackRefFieldName</param>
public void postArchivingCustInvoiceJour(Str       _ackRefFieldName)
{
    AVADAIReportExportTable         avaDAIReportExportTable;
    CustInvoiceJour                 custInvoiceJour;
    FieldId                         refFieldId = fieldName2Id(tableNum(CustInvoiceJour),_ackRefFieldName);
    SalesInvoiceJournalPrint        salesInvoiceJournalPrint;
    SRSPrintDestinationSettings     srsPrintDestinationSetting;

    while select custInvoiceJour
        where  custInvoiceJour.InvoiceDate >= fromDate
           &&  (custInvoiceJour.InvoiceDate <= toDate || toDate == dateNull())
        notexists join avaDAIReportExportTable
            where custInvoiceJour.(refFieldId) == avaDAIReportExportTable.RefNum
    {

        Args        args = new Args();
        args.record(custInvoiceJour);

        salesInvoiceJournalPrint = SalesInvoiceJournalPrint::construct();
        salesInvoiceJournalPrint.parmPrintFormletter(NoYes::Yes);
        salesInvoiceJournalPrint.parmUsePrintManagement(false);


        GiroPrintMgmtFormLetterController formLetterController = SalesInvoiceController::construct();

        formLetterController.parmArgs(args);

        formLetterController.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::SalesOrderInvoice).getDefaultReportFormat());
        formLetterController.parmAVAPrintInMemory(true);
        formLetterController.parmAVAreportRecord(custInvoiceJour);

        formLetterController.parmShowDialog(false);
        formLetterController.parmDialogCaption("@SYS22766");
        SrsReportDataContract  reportContract = formLetterController.parmReportContract();

        srsPrintDestinationSetting  =  reportContract.parmPrintSettings();
        srsPrintDestinationSetting.printMediumType(SRSPrintMediumType::File);
        srsPrintDestinationSetting.fileFormat(SRSReportFileFormat::PDF);
        srsPrintDestinationSetting.fileName(strfmt("%1",custInvoiceJour.InvoiceId));


        salesInvoiceJournalPrint.parmPrinterSettingsFormLetter(srsPrintDestinationSetting.pack());

        args.caller(salesInvoiceJournalPrint);
        args.parmEnumType(enumNum(PrintCopyOriginal));
        args.parmEnum(PrintCopyOriginal::OriginalPrint);


        // formLetterController.parmDefaultCopyPrintJobSettings(srsPrintDestinationSetting);
        // formLetterController.srsPrintDestinationSetting(srsPrintDestinationSetting);
        //   reportContract.parmPrintSettings(srsPrintDestinationSetting);

        formLetterController.startOperation();
    }
}

/// <summary>
/// N.Freidenberger TASK 12587 21.11.2024
/// </summary>
/// <param name = "_ackRefFieldName">_ackRefFieldName</param>
public void postArchivingCustQuotationConfirmJour(Str       _ackRefFieldName)
{
    AVADAIReportExportTable         avaDAIReportExportTable;
    CustQuotationJour               custQuotationjour;
    FieldId                         refFieldId = fieldName2Id(tableNum(CustQuotationjour),_ackRefFieldName);
    Args                            args;
    MenuFunction                    menuFunction;

    while select custQuotationjour
        where  custQuotationjour.QuotationDate >= fromDate
           &&  (custQuotationjour.QuotationDate <= toDate || toDate == dateNull())
        notexists join avaDAIReportExportTable
            where custQuotationjour.(refFieldId) == avaDAIReportExportTable.RefNum
    {
        args = new Args();
        args.record(custQuotationjour);
        args.parmEnum(PrintCopyOriginal::OriginalPrint);
        args.parmEnumType(enumNum(PrintCopyOriginal));


        AVASalesQuotationController_PrintInMemory::main(args);

    }

}
